#!/bin/bash
# Task 244-v137-w5-fill-order -- meshsim v1.37_wip's checks (v1.37_wip/ at 58e8a27, cache-fill-order; updater_wip/tasks/v137-check/make_task.sh), item: proofs-cache.
# v1.37 is v1.36 with Ingress's host link, the Updater and a file store that places pages, behind a switch that is off
# by default, and the master tile's program that runs the whole chip from a packet file (updater_wip/planning/sessions/
# WORKER3). suites = the small inputs built from the pinned sources; the host's side of the proof steps (gold's frames,
# packets and reference images: the 24-run matrix, the three recorded segments, both workloads at 2^29); then
# ./run_tests.sh all --check: every v1.36 step against its v1.36 log, and v1.37's own steps, the proof steps with them;
# the proof runs' figures. check = make check from a clean tree (debug and release, gcc and clang, TSan). faster = the
# same host's side, then the 2^29 runs and the matrix with the link at 2, 4 and 8 bytes a cycle, and the matrix with the
# link as fast as taken (WORKER7; WORKER4's thresholds before), with their figures.
# From an embedded kit. Writes only results/244-v137-w5-fill-order/. Scratch in /tmp, removed first and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/244-v137-w5-fill-order; mkdir -p "$RES"
W=/tmp/v137-244-v137-w5-fill-order; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "e69c69b1e666f6c1e2df101d620af3f1bb936757e0619859957f4346429e0f4a" ] || { echo "kit sha256 mismatch (want e69c69b1e666f6c1e2df101d620af3f1bb936757e0619859957f4346429e0f4a)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2; rm -f "$W/kit.tgz"
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KIT=$W/kit; KS=$KIT/v1.37_wip; REV=58e8a27; ITEM=proofs-cache
# body-proofs-cache -- the body of one Quest task (cache-fill-order, WORKER5): the 37 proof runs on the cache's
# controller and nothing more. 1 convert_delivery (clang release); 2 the small inputs from the pinned sources (Quest
# task 111's kit); 2b the host's side of the proof steps (pipeline/frames/build.sh matrix real 29); these are what the
# runs read. Then 5: proof_run (clang suite) --cache on every run of the sets real (--recorded), matrix and 29, as
# run_tests.sh's proof_set runs them with CACHE_CTL=1, in parallel: 3 + 24 + 10 = 37, each must pass (gold's images,
# every check of proof_run). The figures in proof-numbers.md; the cache's lines in cache-figures.txt.
FAIL=0; T0=$(date +%s); N=$(nproc)
sec() { echo; echo "==== $* ($(date -u +%T), +$(( $(date +%s) - T0 )) s)"; }
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; case $2 in PASS*|SKIPPED*) ;; *) FAIL=1;; esac; }
took() { echo "$1 $(( $(date +%s) - $2 )) s" >> "$RES/TIMES"; }
: > "$RES/VERDICTS"; : > "$RES/TIMES"
sec "the machine"
{ echo "kit: $(cat "$KIT/VERSION")"; echo "host $(hostname); $N CPUs; $(uname -sr)"
  clang++ --version 2>&1 | head -1; g++ --version 2>&1 | head -1; make --version 2>&1 | head -1
  java -version 2>&1 | grep -i version | head -1; cmake --version 2>&1 | head -1; python3 --version 2>&1
  for t in riscv-none-elf-gcc riscv64-unknown-elf-gcc; do echo "$t: $("$t" --version 2>/dev/null | head -1)"; done
  free -g | sed -n 2p; df -BG --output=avail /tmp | tail -1
} 2>&1 | tee "$RES/machine.txt"
verdict machine PASS
[ -n "${DRY:-}" ] && { echo "DRY: stopping after the kit and the machine"; rm -rf "$W"; exit 0; }
if true; then
  sec "1. convert_delivery (clang release), which the inputs' build needs"
  t=$(date +%s)
  if ( cd "$KS" && make -j"$N" MODE=release CC_NAME=clang build/clang-release/convert_delivery ) > "$RES/build-convert.log" 2>&1
  then verdict build-convert PASS; else tail -20 "$RES/build-convert.log"; verdict build-convert FAIL; fi
  took build-convert "$t"

  sec "2. the small inputs, from the pinned sources (jolt-asic-planning from Quest task 111's kit)"
  t=$(date +%s); IN=$W/inputs; INOK=1; K111=$REPO/tasks/111-w27-inputs-evm-zone-29.sh
  if [ -f "$K111" ] && sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$K111" | sed '1d;$d' | base64 -d > "$W/kit111.tgz" \
     && [ "$(sha256sum "$W/kit111.tgz" | cut -d' ' -f1)" = 3ddbcebf08ff8cf3aaf75c1b88fd5eceb93a2a62ce2c942b42ef55f14c0a00b3 ] \
     && mkdir -p "$W/i" && tar -xzf "$W/kit111.tgz" -C "$W/i" k/jap k/libelf; then
    rm -f "$W/kit111.tgz"
    [ -e /usr/include/libelf.h ] || [ -e /usr/include/libelf/libelf.h ] || { export LIBELF_PREFIX=$W/i/k/libelf; echo "no system libelf.h: task 111's kit's"; }
    for w in evm-zone cyclone; do
      OUT=$IN JAP_DIR=$W/i/k/jap CLASSES=$KIT/classes GOLD_FORMAT="v1.2 v1.3" MESHSIM_COMMIT=$REV JOBS=$N \
        bash "$KS/pipeline/inputs/build.sh" "$w" small > "$RES/inputs-$w.log" 2>&1 || { tail -15 "$RES/inputs-$w.log"; INOK=0; }
      grep -v INFO "$RES/inputs-$w.log" | tail -3
    done
    for r in evm-zone-23 cyclone-22; do
      OUT=$IN bash "$KS/pipeline/inputs/check.sh" "$r" > "$RES/inputs-check-$r.txt" 2>&1 || INOK=0; tail -1 "$RES/inputs-check-$r.txt"
    done
    du -sh "$IN" 2>/dev/null
  else echo "Quest task 111's kit is not at $K111, or differs"; INOK=0; fi
  [ $INOK = 1 ] && verdict inputs-small PASS || verdict inputs-small FAIL
  took inputs-small "$t"

  sec "2b. the host's side of the proof steps: gold's frames, packets and references (pipeline/frames/build.sh)"
  t=$(date +%s)
  ( cd "$KS" && make -j"$N" MODE=suite CC_NAME=clang build/clang-suite/packetize ) > "$RES/build-packetize.log" 2>&1 || tail -5 "$RES/build-packetize.log"
  if [ $INOK = 1 ] && OUT=$IN JAP_DIR=$W/i/k/jap GOLD_CLASSES=$KIT/classes-frames PACKETIZE=$KS/build/clang-suite/packetize \
       bash "$KS/pipeline/frames/build.sh" matrix real 29 > "$RES/frames.log" 2>&1
  then grep -v JAVA_TOOL "$RES/frames.log" | tail -16; verdict frames PASS
  else tail -8 "$RES/frames.log" 2>/dev/null; verdict frames FAIL; fi
  cat "$IN"/v137/*/SHA256SUMS > "$RES/frames-sha256.txt" 2>/dev/null
  took frames "$t"
fi

sec "5. the 37 proof runs on the cache's controller (proof_run --cache)"
t=$(date +%s)
( cd "$KS" && make -j"$N" MODE=suite CC_NAME=clang build/clang-suite/proof_run ) > "$RES/build-proof_run.log" 2>&1 || tail -5 "$RES/build-proof_run.log"
mkdir -p "$W/runs"; : > "$W/jobs"
for set in 29 matrix real; do                          # the long ones first
  while read -r name n windows list; do for s in $list; do echo "$set $name $n $windows $s" >> "$W/jobs"; done; done < "$IN/v137/$set/RUNS"
done
wc -l < "$W/jobs"
one() {   # SET NAME N WINDOWS S
  local d=$IN/v137/$1 rec=""
  [ "$1" = real ] && rec="--recorded $2"
  cd "$KS" && MESHSIM_INPUTS="$IN" ./build/clang-suite/proof_run "$d/$2.frames" --packets "$d/$2.packets" --asics "$3" --segment "$5" \
    --windows "$4" --gold "$d/$2-s$5.images.txt" $rec --quiet --cache > "$W/runs/$1.$2.s$5.log" 2>&1 || echo "FAIL proof_run $2, s $5: exit $?" >> "$W/runs/$1.$2.s$5.log"
}
export -f one; export IN KS W
xargs -P "$N" -L 1 bash -c 'one "$@"' _ < "$W/jobs"
for p in real:3 matrix:24 29:10; do
  set=${p%%:*}; want=${p##*:}
  cat "$W"/runs/$set.*.log > "$RES/proof-$set.log" 2>/dev/null
  got=$(grep -c '^PASS proof_run' "$RES/proof-$set.log"); bad=$(grep -c '^FAIL' "$RES/proof-$set.log")
  if [ "$got" = "$want" ] && [ "$bad" = 0 ]; then verdict "proof-$set" "PASS-$got-runs"; else verdict "proof-$set" "FAIL-$got-of-$want-passed"; fi
done
( cd "$KS" && python3 tests/proof_numbers.py "$RES"/proof-real.log "$RES"/proof-matrix.log "$RES"/proof-29.log --frames ) > "$RES/proof-numbers.md" 2>&1
grep -h 'the cache:\|LPDDR:' "$RES"/proof-*.log > "$RES/cache-figures.txt" 2>/dev/null
tail -3 "$RES/proof-numbers.md"
took proofs "$t"

sec "end"
cat "$RES/VERDICTS"; cat "$RES/TIMES"
rm -rf "$W"
[ $FAIL = 0 ] && echo "ALL PASS" || echo "FAILED"
exit $FAIL
